typedef unsigned long uint64;

class pstring {
    uint64 pchunk[4];
    void pack_string(const char *);

public:
    pstring(const char *text) {
        pack_string(text);
    }

    bool operator==(const pstring &other) const {
        for (unsigned i = 0; i < 4; ++i) {
            if (pchunk[i] != other.pchunk[i])
                return false;
        }
        return true;
    }
};

